mapper.insert:
insert into kb_index_policy_version (
    version_no, version_label, status, payload_json, fingerprint, check_report,
    published_by, published_at, create_by, create_time, remark
) values (
    #{versionNo}, #{versionLabel}, #{status}, #{payloadJson}, #{fingerprint}, #{checkReport},
    #{publishedBy}, #{publishedAt}, #{createBy}, current_timestamp, #{remark}
)

mapper.select:
select j.*, k.kb_name
  from kb_index_job j
  left join kb_knowledge k on k.kb_id = j.kb_id
 where j.kb_id = #{kbId}
 order by j.job_id desc
 limit #{limit}
